# DK RNX.  Rønne H - Nexø
#
let rn = path("d3.dk.rnx");

with detail = 4, railway = :third :narrow :g1000 :pax :removed {
    with link = "point.dk.Rønne-H", railway = :station {
        track(rn[:roh.a, :roh + 0.5sw]);
        marker(:right :de.bf, rn[:roh] >> 0.5lt);
        station(:left, rn[:roh] << 0.5lt + (-1.8dt, 1.1dt),
            span(:bold, "Rønne H"), "RNX: 0,0"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:roh + 0.49sw, :roh + 0.76km]);
        line_label(:left:se, rn[:roh + 0.75km] << 0.5lt, "RNX");
        track(rn[:roh + 0.74km, :ron - 100m]);
    }

    with link = "point.dk.Rønne-Nord", railway = :station {
        track(rn[:ron - 101m, :ron.ya]);
        track(
                rn[:ron - 101m, :ron - 100m]
            --  rn[:ron - 100m + 1dl, :ron.ya] << 1lo
        );
        marker(:right :de.bf, rn[:ron] >> 0.5lt);
        station(:top, rn[:ron] << 1lo << 0.5lt + (-1.5dt, -0.8dt),
            span(:bold, "Rønne Nord "),
            hbox(:center:top,
                vbox(:right:top, "RSV: ", "RNX: "),
                vbox(:sep:top,
                    hbox(:sep:base, "1,", anchor(), "5"),
                    hbox(:sep:base, "1,", anchor(), "5")
                )
            )
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:ron.ya - 0.1dl, :roo - 0.49sw]);
    }

    with link = "point.dk.Rønne-Østre", railway = :station {
        track(rn[:roo - 0.5sw, :roo + 0.5sw]);
        marker(:left :de.hp, rn[:roo] << 1lt);
        station(:right, rn[:roo] << 1lt << 1sh + (2dt, 0.8dt),
            "Rønne Østre", "RNX: 2,9"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:roo + 0.49sw, :rab + 0.1dl]);
    }

    with link = "point.dk.Rabekkeværket", railway = :station {
        marker(:left :de.anst, rn[:rab] << 0.5lt);
        station(:right, rn[:rab] << 0.5lt << 1sh + (1.5dt, 0.4dt),
            span(:small, "Rabekkeværket"), "RNX: 4,3"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:rab - 0.1dl, :rob - 0.49sw]);
    }

    with link = "point.dk.Robbedale", railway = :station {
        track(rn[:rob - 0.5sw, :rob + 0.5sw]);
        marker(:left :de.hp, rn[:rob] << 0.5lt);
        station(:top, rn[:rob] << 1lt << 1sh + (1.8dt, -0.8dt),
            "Robbedale", "RNX: 5,6"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:rob + 0.49sw, :kol - 0.49sw]);
    }

    with link = "point.dk.Køllergårde", railway = :station {
        track(rn[:kol - 0.5sw, :kol + 0.5sw]);
        marker(:right :de.bf, rn[:kol] >> 0.5lt);
        station(:bottom, rn[:kol] >> 0.5lt >> 1sh >> 0.8dt,
            "Køllergårde", "RNX: 8,6"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:kol + 0.49sw, :nyl - 0.49sw]);
    }

    with link = "point.dk.Nylars", railway = :station {
        track(rn[:nyl - 0.5sw, :nyl + 0.5sw]);
        marker(:right :de.hp, rn[:nyl] >> 0.5lt);
        station(:bottom, rn[:nyl] >> 0.5lt >> 1sh >> 0.8dt,
            "Nylars", "RNX: 10,2"
