    }

    with link = "line.dk.RNX" {
        track(rn[:nyl + 0.49sw, :lob - 0.49sw]);
    }

    with link = "point.dk.Lobbæk", railway = :station {
        track(rn[:lob - 0.5sw, :lob + 0.5sw]);
        marker(:right :de.bf, rn[:lob] >> 0.5lt);
        station(:bottom, rn[:lob] >> 0.5lt >> 1sh >> 0.9dt,
            "Lobbæk", "RNX: 11,6"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:lob + 0.49sw, :smo - 0.49sw]);
    }

    with link = "point.dk.Smørenge", railway = :station {
        track(rn[:smo - 0.5sw, :smo + 0.5sw]);
        marker(:right :de.hp, rn[:smo] >> 0.5lt);
        station(:bottom, rn[:smo] >> 0.5lt >> 1sh + (1.5dt, 0.8dt),
