        );
    }

    with link = "line.dk.RNX" {
        track(rn[:smo + 0.49sw, :tvi - 0.49sw]);
    }

    with link = "point.dk.Tvillinggårde", railway = :station {
        track(rn[:tvi - 0.5sw, :tvi + 0.5sw]);
        marker(:left :de.hp, rn[:tvi] << 0.5lt);
        station(:top, rn[:tvi] << 0.5lt << 1sh << 0.6dt,
            "Tvillinggårde", "RNX: 15,0"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:tvi + 0.49sw, :tvi + 0.71km]);
        line_label(:right:ne, rn[:tvi + 0.7km] >> 0.5lt, "RNX");
        track(rn[:tvi + 0.69km, :aki.ya - 0.99seg]);
        track(:station, rn[:aki.ya - 1seg, :aki.ya + 01.dl]);
        track(:lor, rn[:aki.ya, :aki - 0.49sw]);
    }

    with link = "point.dk.Aakirkeby", railway = :station {
        track(rn[:aki - 0.5sw, :aki + 100m + 2dl]);
        track(
                rn[:aki - 0.5sw, :aki + 100m] << 1ls << 1lt
            --  rn[:aki + 100m + 1dl, :aki + 100m + 1.1dl]
        );
        marker(:right :de.bf, rn[:aki] >> 0.5lt);
        station(:bottom, rn[:aki] >> 0.5lt >> 1sh >> 0.8dt,
            span(:bold, "Aakirkeby"),
            hbox(:center:top,
                vbox(:right:top, "AKA: ", "RNX: "),
                vbox(:sep:top,
                    hbox(:sep:base, "0,", anchor(), "0"),
                    hbox(:sep:base, "17,", anchor(), "0")
                )
            )
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:aki + 0.49sw - 0.1dl, :aki + 0.71km]);
        line_label(:left:w, rn[:aki + 0.7km] << 0.5lt, (0dt, -0.2dt), "RNX");
        track(rn[:aki + 0.69km, :ugl - 0.49sw]);
    }

    with link = "point.dk.Ugleenge", railway = :station {
        track(rn[:ugl - 0.5sw, :ugl + 0.5sw]);
        marker(:left :de.bf, rn[:ugl] << 0.5lt);
        station(:top, rn[:ugl] << 0.5lt << 1sh + (1.5dt, -0.8dt),
