    }

    with link = "line.dk.RNX" {
        track(rn[:bal + 0.49sw, :nek - 0.49sw]);
    }

    with link = "point.dk.", railway = :station {
        track(rn[:nek- 0.5sw, :nek + 0.5sw]);
        marker(:left :de.bf, rn[:nek] << 0.5lt);
        station(:right:left_align, rn[:nek] >> 0.5lt + (1.5dt, 1.1dt),
            span(:bold, "Neksø"), " RNX: 36,6"
        );
